<div class="tf-column-heading"><span>{{ $label }}@if(request('sort')===$column)<i class="fas fa-arrow-{{ request('direction')==='desc'?'down':'up' }} tf-sort-indicator"></i>@endif</span><button type="button" class="tf-column-filter {{ array_key_exists($column,request('columns',[]))||array_key_exists($column,request('exclude',[]))?'is-active':'' }}" data-column="{{ $column }}" data-label="{{ $filterLabel ?? $label }}" aria-label="Filter dan urutkan {{ $label }}" aria-expanded="false"><i class="fas fa-filter"></i></button></div>
